def findInitialVertex(self, allVertices):
    i = len(allVertices) - 1
    while i >= 0:
        if allVertices[i].x == self.startVertex.x and allVertices[i].y == self.startVertex.y:
            break
        i -= 1
    initial_i = i
    while i < initial_i + len(allVertices) - 1:
        j = self.indexInRange(i)
        if (j not in self.notchVertices and j + len(allVertices) not in self.notchVertices and (j - len(allVertices) not in self.notchVertices)) and (not self.calcAngle(allVertices[j - 1], allVertices[j], allVertices[j + 1])):
            self.indexOfVertex = self.indexInRange(j + 1)
            self.vertexIndexOfNextPoly.append(j)
            self.vertexIndexOfNextPoly.append(self.indexOfVertex)
            break
        else:
            i = i + 1

