def get_stacktrace_config(configs: List[RepositoryProjectPathConfig], ctx: Dict[str, Optional[str]]) -> StacktraceLinkOutcome:
    filepath = str(ctx.get('file', ''))
    result: StacktraceLinkOutcome = {'source_url': None, 'error': None, 'current_config': None, 'iteration_count': 0, 'is_munged': False}
    for config in configs:
        outcome: ReposityLinkOutcome = {}
        munging_outcome: ReposityLinkOutcome = {}
        if ctx['platform'] in ['java', 'cocoa', 'other']:
            (munging_outcome, next_iteration_count) = try_path_munging(config, filepath, ctx, result['iteration_count'])
            result['iteration_count'] = next_iteration_count
            if munging_outcome.get('error') == 'stack_root_mismatch':
                result['error'] = 'stack_root_mismatch'
                continue
        if not munging_outcome:
            if not filepath.startswith(config.stack_root):
                result['error'] = 'stack_root_mismatch'
                continue
            outcome = get_link(config, filepath, ctx.get('commit_id'), ctx.get('group_id'), ctx.get('abs_path'))
            result['iteration_count'] += 1
        if munging_outcome:
            outcome = munging_outcome
            result['is_munged'] = True
        result['current_config'] = {'config': config, 'outcome': outcome, 'repository': config.repository}
        if outcome.get('sourceUrl') and outcome['sourceUrl']:
            result['source_url'] = outcome['sourceUrl']
            return result
    return result

