def concretize_compiler_flags(self, spec):
    if not (spec.architecture.platform_os and spec.architecture.target):
        return True
    compiler_match = lambda other: spec.compiler == other.compiler and spec.architecture == other.architecture
    ret = False
    for flag in spack.spec.FlagMap.valid_compiler_flags():
        if flag not in spec.compiler_flags:
            spec.compiler_flags[flag] = list()
        try:
            nearest = next((p for p in spec.traverse(direction='parents') if compiler_match(p) and p is not spec and (flag in p.compiler_flags)))
            nearest_flags = set(nearest.compiler_flags.get(flag, []))
            flags = set(spec.compiler_flags.get(flag, []))
            if nearest_flags - flags:
                spec.compiler_flags[flag] = list(nearest_flags | flags)
                ret = True
        except StopIteration:
            pass
    try:
        compiler = spack.compilers.compiler_for_spec(spec.compiler, spec.architecture)
    except spack.compilers.NoCompilerForSpecError:
        if self.check_for_compiler_existence:
            raise
        return ret
    for flag in compiler.flags:
        config_flags = set(compiler.flags.get(flag, []))
        flags = set(spec.compiler_flags.get(flag, []))
        spec.compiler_flags[flag] = list(config_flags | flags)
        if config_flags - flags:
            ret = True
    return ret

def run(self):
    latest_state = None
    with kombu.Connection(self._amqp_url) as conn:
        q = conn.SimpleQueue('brozzler.sites.unclaimed')
        while not self._shutdown_requested.is_set():
            try:
                q_empty = False
                if len(q) > 0:
                    try:
                        self._claim_site(q)
                    except kombu.simple.Empty:
                        q_empty = True
                    except KeyError:
                        if latest_state != 'browsers-busy':
                            self.logger.info('all {} browsers are busy'.format(self._max_browsers))
                            latest_state = 'browsers-busy'
                else:
                    q_empty = True
                if q_empty:
                    if latest_state != 'no-unclaimed-sites':
                        latest_state = 'no-unclaimed-sites'
                time.sleep(0.5)
            except OSError as e:
                self.logger.warn('continuing after i/o exception (from rabbitmq?)', exc_info=True)

def _request_params(self):
    params = super(FileRequest, self)._request_params
    data = self.files or {}
    data['json'] = ('json', json.dumps(self.data), 'application/json')
    callback = self.progress_callback or (lambda x: x)
    m = MultipartEncoder(data)
    params['json'] = None
    params['data'] = MultipartEncoderMonitor(m, callback)
    params['headers'] = {'Content-Type': params['data'].content_type}
    return params

def on_new_tab(event: utils.EventWithData) -> None:
    tab = event.data_widget()
    if isinstance(tab, tabs.FileTab):
        tab.settings.add_option('langserver_command', None, type=Optional[str])
        tab.settings.add_option('langserver_language_id', None, type=Optional[str])
        tab.settings.add_option('langserver_port', None, type=Optional[int])
        for virtual_event in ['<<PathChanged>>']:
            tab.bind(virtual_event, functools.partial(switch_langservers, tab), add=True)
        switch_langservers(tab)

def _build_instance_node(self, instance):
    flavor = instance.flavor
    instance_attributes = {'uuid': instance.id, 'name': instance.name, 'memory': flavor['ram'], 'disk': flavor['disk'], 'disk_capacity': flavor['disk'], 'vcpus': flavor['vcpus'], 'state': getattr(instance, 'OS-EXT-STS:vm_state'), 'metadata': instance.metadata, 'project_id': instance.tenant_id, 'locked': instance.locked}
    return element.Instance(**instance_attributes)

def create_router_on_l3_agent(self, agent_id, **kwargs):
    uri = '/agents/%s/l3-routers' % agent_id
    return self.create_resource(uri, kwargs, expect_empty_body=True)

def _validator_items(self, field, value):
    if isinstance(value, Mapping):
        self._validator_schema(field, value)
    else:
        for (i, schema) in enumerate(value):
            self._validator_bulk_schema((field, i), schema)

def hint(self, index):
    self.__check_okay_to_chain()
    if index is None:
        self.__hint = None
        return self
    if not isinstance(index, types.ListType):
        raise TypeError('hint takes a list specifying an index')
    self.__hint = pymongo._index_document(index)
    return self

